// Counts the visits of one message class, through the visitor its own dispatch is seen by.
template <typename Visitor, typename Expected>
struct Seen : Visitor {
    std::size_t matched = 0;

    void visit(const Expected&) override { ++matched; }
};

// Hands the message a message's own branch selects (an OUCH order in a SoupBinTCP data packet, a
// CTA message within its category) on to the counter of the dispatch below: the message holding
// the branch is seen through the visitor its own dispatch is seen by.
template <typename Visitor, typename Holder, auto Reach, typename Inner>
struct Within : Visitor {
    Inner inner;
    std::size_t matched = 0;

    void visit(const Holder& holder) override {
        if (const auto* held = Reach(holder)) {
            const std::size_t before = inner.matched;
            held->accept(inner);
            matched += inner.matched - before;
        }
    }
};

// Decode every datagram in a capture, require the expected message to be visited, and
// require every datagram to encode back to the bytes it came from.
template <typename Packet, typename Counter>
void expect_seen(const char* name, const char* relative) {
    std::vector<std::pair<std::string, std::int64_t>> sources;
    sources.emplace_back(root() + "/" + relative, 0);

    packet::PcapIterator captures(sources);
    Counter seen;
    std::vector<std::byte> buffer;

    std::size_t frames = 0;
    std::size_t messages = 0;
    std::size_t undecodable = 0;
    std::size_t mismatched = 0;

    while (captures.advance()) {
        const packet::Frame frame(captures.data(), captures.length());

        if (!frame.valid()) { continue; }

        ++frames;
        Packet decoded;

        try {
            decoded.decode(frame.payload, frame.payload_len);
        } catch (const protocol::DecodeError& error) {
            ++undecodable;
            std::printf("  undecodable datagram: %s\n", error.what());
            continue;
        }

        messages += decoded.frames().size();
        decoded.accept(seen);

        buffer.assign(decoded.encoded_size(), std::byte{ 0 });
        const std::size_t written = decoded.encode(buffer.data(), buffer.size());

        if (written != frame.payload_len || std::memcmp(buffer.data(), frame.payload, written) != 0) {
            ++mismatched;
        }
    }

    const std::size_t matched = seen.matched;

    if (undecodable > 0) {
        std::printf("FAIL %s: %zu datagrams did not decode\n", name, undecodable);
        ++failures;
        return;
    }

    if (mismatched > 0) {
        std::printf("FAIL %s: %zu datagrams did not encode back to their bytes\n", name, mismatched);
        ++failures;
        return;
    }

    if (frames == 0) {
        std::printf("FAIL %s: no transport frames in capture\n", name);
        ++failures;
        return;
    }

    if (messages == 0) {
        std::printf("FAIL %s: no messages parsed from capture\n", name);
        ++failures;
        return;
    }

    if (matched == 0) {
        std::printf("FAIL %s: parsed %zu messages, none of the expected type\n", name, messages);
        ++failures;
        return;
    }

    std::printf("ok   %s: %zu of %zu messages\n", name, matched, messages);
}

// Require the expected message through the visitor of the tree's own dispatch.
template <typename Packet, typename Visitor, typename Message>
void expect(const char* name, const char* relative) {
    expect_seen<Packet, Seen<Visitor, Message>>(name, relative);
}

